// Injection guard (IN) + smalltalk/greeting intercept. Fence user text as data.
const item = $input.first().json;
const rawQuestion = (item.chatInput != null ? String(item.chatInput) : '').trim();
const sessionId = (item.sessionId != null && String(item.sessionId).length) ? String(item.sessionId) : 'anon';

const injectionPatterns = [
  /ignore\s+(?:all\s+)?(?:your\s+)?(?:previous\s+|prior\s+|above\s+)?instructions?/gi,
  /disregard\s+(?:all\s+)?(?:your\s+)?(?:previous\s+|prior\s+)?instructions?/gi,
  /forget\s+(?:all\s+)?(?:your\s+)?(?:previous\s+|prior\s+)?instructions?/gi,
  /reveal\s+(?:your\s+)?(?:system\s+)?prompt/gi,
  /show\s+(?:me\s+)?(?:your\s+)?(?:system\s+)?prompt/gi,
  /what\s+(?:is|are)\s+your\s+(?:system\s+)?(?:instructions?|prompt)/gi,
  /print\s+(?:your\s+)?(?:system\s+)?(?:instructions?|prompt)/gi,
  /act\s+as\s+(?:a\s+|an\s+)?/gi,
  /you\s+are\s+now\s+/gi,
  /pretend\s+(?:to\s+be|you\s+are)/gi,
  /developer\s+mode/gi,
  /system\s*:\s*/gi,
  /\bDAN\b/g
];

let injectionDetected = false;
let neutralised = rawQuestion;
for (const re of injectionPatterns) {
  if (re.test(neutralised)) { injectionDetected = true; }
  neutralised = neutralised.replace(re, '[redacted-instruction]');
}

// Smalltalk / greeting / capability intercept: short-circuit before retrieval so
// "hi", "thanks", "what can you do" get a friendly reply, not a legal data dump.
const q = rawQuestion.toLowerCase().replace(/[!.,?]+$/,'').trim();
const greet = /^(hi|hey|hello|yo|hiya|howdy|good (morning|afternoon|evening)|sup|hi there|hello there)$/;
const thanks = /^(thanks|thank you|ty|thx|cheers|much appreciated|great|awesome|cool|nice|ok|okay|got it)$/;
const capability = /\b(what can you do|who are you|what are you|what do you do|help|how (do|does) (you|this) work|what is this)\b/;
let isSmalltalk = false, smalltalkReply = '';
if (greet.test(q)) {
  isSmalltalk = true;
  smalltalkReply = "Hi — I'm a Virtual Lawyer for Australian criminal law. Ask me about an offence or penalty under the Commonwealth Criminal Code or NSW criminal legislation, and I'll answer with the exact sections, e.g. \"What's the penalty for larceny in NSW?\" or \"Elements of murder?\". (General legal information, not legal advice.)";
} else if (thanks.test(q)) {
  isSmalltalk = true;
  smalltalkReply = "You're welcome. Ask me another Australian criminal-law question whenever you like. (General legal information, not legal advice.)";
} else if (capability.test(q) && q.split(' ').length <= 8) {
  isSmalltalk = true;
  smalltalkReply = "I'm a Virtual Lawyer for Australian criminal law. I answer questions about offences, elements and penalties under the Commonwealth Criminal Code and NSW criminal legislation (Crimes Act 1900, Drug Misuse & Trafficking Act, Road Transport Act, and more) — always citing the exact section, and refusing if it's not in my sources. Try: \"penalty for supplying a prohibited drug in NSW?\" (General legal information, not legal advice.)";
}

const retrievalQuery = rawQuestion;
return [{ json: {
  sessionId, rawQuestion, retrievalQuery,
  neutralisedQuestion: neutralised, injectionDetected,
  isSmalltalk, smalltalkReply
} }];

// Combine retrieval results with the guarded question (carried from Injection Guard).
const fs = require('fs');
const guard = $('Injection Guard (IN)').first().json;
const search = $input.first().json;
const hits = (search && Array.isArray(search.result)) ? search.result : [];

const sections = hits.map(h => {
  const p = h.payload || {};
  return { score: h.score, citation: p.citation || '', act: p.act || '', section_number: p.section_number || '', title: p.title || '', jurisdiction: p.jurisdiction || '', text: p.text || '' };
});

// Smalltalk short-circuits: force score 0 so the Score Gate routes to the friendly branch.
const isSmalltalk = !!guard.isSmalltalk;
const topScore = isSmalltalk ? 0 : (sections.length ? Number(sections[0].score) : 0);

const contextBlock = sections.map((s, i) => `[Section ${i + 1}] ${s.citation}\n${s.text}`).join('\n\n---\n\n');
const citationList = sections.map(s => s.citation).filter(Boolean);
const retrievedSummary = sections.map(s => `${s.citation} (score ${Number(s.score).toFixed(3)})`).join('; ');

const DIR = '/home/node/.n8n/vlawyer_logs';
let prior = [];
try {
  const raw = fs.readFileSync(DIR + '/sessions.jsonl', 'utf8');
  const rows = raw.split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch (e) { return null; } }).filter(Boolean);
  prior = rows.filter(r => r.sessionId === guard.sessionId).slice(-5);
} catch (e) { prior = []; }
const historyBlock = prior.length ? prior.map(r => `User: ${r.question}\nAssistant: ${r.answer}`).join('\n\n') : '(no prior turns in this session)';

return [{ json: {
  sessionId: guard.sessionId, rawQuestion: guard.rawQuestion,
  neutralisedQuestion: guard.neutralisedQuestion, injectionDetected: guard.injectionDetected,
  isSmalltalk, smalltalkReply: guard.smalltalkReply || '',
  topScore, sections, citationList, retrievedSummary, contextBlock, historyBlock
} }];

// Groundedness / citation guard (OUT).
const proc = $('Process Retrieval (score+ctx)').first().json;
const llm = $input.first().json;

let answer = '';
try { answer = llm.choices[0].message.content || ''; } catch (e) { answer = ''; }
answer = String(answer).trim();

const disclaimer = 'This is general legal information, not legal advice.';
const refusalText = "I can't find an Australian criminal-law provision that covers that. I only answer from the Commonwealth Criminal Code and NSW criminal legislation in my sources, and won't guess. (This is general legal information, not legal advice.)";

// Build the set of acceptable citation anchors from retrieved sections PLUS the
// citations already grounded earlier in THIS session (so follow-ups such as
// 'the maximum penalty for that' can cite a section grounded on a prior turn,
// even though retrieval for the bare follow-up would not resurface it).
const sd = $getWorkflowStaticData('global');
const priorAll = Array.isArray(sd.sessions) ? sd.sessions : [];
const priorCitations = priorAll
  .filter(r => r.sessionId === proc.sessionId)
  .slice(-5)
  .flatMap(r => (r.citations ? String(r.citations).split(' | ') : []))
  .filter(Boolean);

// Derive act names and section numbers from prior-session citation strings,
// e.g. 's 117 Crimes Act 1900 (NSW)'.
const priorSectionNums = priorCitations.map(c => {
  const m = /\bs\s*([0-9A-Za-z.]+)/.exec(c);
  return m ? m[1] : null;
}).filter(Boolean);
const priorActs = priorCitations.map(c => c.replace(/^s\s*[0-9A-Za-z.]+\s*/, '').trim()).filter(Boolean);

const acts = [...new Set(proc.sections.map(s => s.act).filter(Boolean).concat(priorActs))];
const sectionNums = [...new Set(proc.sections.map(s => s.section_number).filter(Boolean).concat(priorSectionNums))];
const citations = [...new Set(proc.sections.map(s => s.citation).filter(Boolean).concat(priorCitations))];

const lower = answer.toLowerCase();

// (a) Does the answer reference at least one retrieved Act or exact citation?
let actCited = citations.some(c => c && lower.includes(c.toLowerCase()))
  || acts.some(a => a && lower.includes(a.toLowerCase()));

// (b) Does the answer reference at least one retrieved section number, in an 's NUM' form?
let sectionCited = sectionNums.some(n => {
  if (!n) return false;
  const esc = String(n).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('\\bs\\s*' + esc + '\\b', 'i');
  return re.test(answer);
});

let flagType = null;
if (answer.length === 0) {
  flagType = 'GROUNDEDNESS_FAIL';
} else if (!actCited && !sectionCited) {
  // No reference to any retrieved Act OR section number.
  flagType = 'NO_CITATION';
}

// If the model itself refused appropriately (said it cannot find it), that is allowed
// as long as it did not fabricate. Treat an explicit no-source answer as grounded refusal.
const modelRefused = /cannot find|could not find|not (?:in|contained in) (?:my|the retrieved)/i.test(answer);
if (flagType && modelRefused) {
  flagType = null;
}

const blocked = flagType !== null;
const finalAnswer = blocked ? refusalText : answer;

return [{ json: {
  sessionId: proc.sessionId,
  rawQuestion: proc.rawQuestion,
  topScore: proc.topScore,
  retrievedSummary: proc.retrievedSummary,
  citationList: proc.citationList,
  modelAnswer: answer,
  finalAnswer,
  blocked,
  flagType
} }];

// Persist session turn + any guardrail fire to disk (JSONL), then emit chat response. (ANSWER branch)
const fs = require('fs');
const g = $input.first().json;
const DIR = '/home/node/.n8n/vlawyer_logs';
try { fs.mkdirSync(DIR, { recursive: true }); } catch (e) {}
const ts = new Date().toISOString();

if (g.blocked) {
  const flag = { ts, sessionId: g.sessionId, question: g.rawQuestion, flag_type: g.flagType, score: g.topScore, retrieved_sections: g.retrievedSummary };
  try { fs.appendFileSync(DIR + '/flags.jsonl', JSON.stringify(flag) + '\n'); } catch (e) {}
}
const sess = { ts, sessionId: g.sessionId, question: g.rawQuestion, answer: g.finalAnswer, citations: (g.citationList || []).join(' | ') };
try { fs.appendFileSync(DIR + '/sessions.jsonl', JSON.stringify(sess) + '\n'); } catch (e) {}

return [{ json: { output: g.finalAnswer } }];

// Score gate failed. If smalltalk -> friendly reply (no flag). Else -> refusal (flag).
const fs = require('fs');
const p = $input.first().json;
const DIR = '/home/node/.n8n/vlawyer_logs';
try { fs.mkdirSync(DIR, { recursive: true }); } catch (e) {}
const ts = new Date().toISOString();

if (p.isSmalltalk) {
  const reply = p.smalltalkReply || "Hi — ask me an Australian criminal-law question and I'll answer with the exact sections. (General legal information, not legal advice.)";
  const sess = { ts, sessionId: p.sessionId, question: p.rawQuestion, answer: reply, citations: '' };
  try { fs.appendFileSync(DIR + '/sessions.jsonl', JSON.stringify(sess) + '\n'); } catch (e) {}
  return [{ json: { output: reply } }];
}

const refusalText = "I can't find an Australian criminal-law provision that covers that. I only answer from the Commonwealth Criminal Code and NSW criminal legislation in my sources, and won't guess. (This is general legal information, not legal advice.)";
const flag = { ts, sessionId: p.sessionId, question: p.rawQuestion, flag_type: 'REFUSED_LOW_SCORE', score: p.topScore, retrieved_sections: p.retrievedSummary };
try { fs.appendFileSync(DIR + '/flags.jsonl', JSON.stringify(flag) + '\n'); } catch (e) {}
const sess = { ts, sessionId: p.sessionId, question: p.rawQuestion, answer: refusalText, citations: '' };
try { fs.appendFileSync(DIR + '/sessions.jsonl', JSON.stringify(sess) + '\n'); } catch (e) {}
return [{ json: { output: refusalText } }];
